import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './ClienteList.css'; // Importando o CSS

const ClienteList = ({ setSelectedClienteId }) => {
  const [clientes, setClientes] = useState([]);
  const [search, setSearch] = useState('');

  // Função para carregar os clientes
  const loadClientes = async (searchTerm = '') => {
    try {
      const url = searchTerm
        ? `http://localhost:8080/clientes?search=${searchTerm}`
        : `http://localhost:8080/clientes`;
      const response = await axios.get(url);
      setClientes(response.data);
    } catch (error) {
      console.error('Erro ao carregar os clientes:', error);
    }
  };

  // Efeito para carregar os clientes ao montar o componente
  useEffect(() => {
    loadClientes(); // Carregar clientes
  }, []);

  // Função para lidar com a mudança no campo de busca
  const handleSearchChange = (e) => {
    const searchTerm = e.target.value;
    setSearch(searchTerm);
    loadClientes(searchTerm); // Carregar clientes com o novo termo de busca
  };

  // Função para deletar um cliente
  const deleteCliente = async (id) => {
    try {
      await axios.delete(`http://localhost:8080/clientes/${id}`);
      setClientes(clientes.filter(cliente => cliente.id !== id)); // Atualizar a lista localmente
      alert('Cliente deletado com sucesso!');
    } catch (error) {
      console.error('Erro ao deletar o cliente:', error);
      alert('Erro ao deletar o cliente!');
    }
  };

  // Função para navegar para a página de atualização
  const updateCliente = (id) => {
    setSelectedClienteId(id);
    // Aqui você pode redirecionar para uma página de edição ou mostrar um formulário de atualização
    // Exemplo: history.push(`/clientes/editar/${id}`);
  };

  return (
    <div className="cliente-list-container">
      <h2>Lista de Clientes</h2>

      {/* Formulário de busca */}
      <div className="search-form">
        <label htmlFor="search">Buscar Cliente:</label>
        <input
          type="text"
          id="search"
          value={search}
          onChange={handleSearchChange}
          placeholder="Digite o nome ou email do cliente"
        />
      </div>

      {/* Lista de Clientes */}
      <div className="clientes-list">
        {clientes.length === 0 ? (
          <p>Nenhum cliente encontrado.</p>
        ) : (
          clientes.map(cliente => (
            <div key={cliente.id} className="cliente-card">
              <h3>{cliente.nome}</h3>
              <p>{cliente.email}</p>
              <p>{cliente.telefone}</p>

              {/* Botões de Atualizar e Deletar */}
              <div className="cliente-actions">
                <button onClick={() => updateCliente(cliente.id)} className="btn-update">
                  Atualizar
                </button>
                <button onClick={() => deleteCliente(cliente.id)} className="btn-delete">
                  Deletar
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default ClienteList;
